include!("phi24_lattice_core.rs");
const N:usize=648;
const PUBLIC_ELEMENTS:usize=4096;
const PACKED:&[u8]=include_bytes!("phi24-digits6.bin");
fn asset_digit(index:usize)->i8{let j=index*6;let k=j/8;let shift=j%8;let a=PACKED[k]as u16;let b=PACKED.get(k+1).copied().unwrap_or(0)as u16;let v=((a|(b<<8))>>shift)&63;if v>=32{(v as i16-64)as i8}else{v as i8}}
fn congruent(a:&[u128],r:&[[i8;6]])->bool{for(e,poly)in a.chunks_exact(N).enumerate(){for j in 0..81{let mut product=[0i64;9];for d in 0..6{let(u,v)=WEIGHTS[0][d];for k in 0..8{let x=r[e*N+j+81*k][d]as i64;product[k]+=x*u;product[k+1]+=x*v;}}let top=product[8];product[0]-=top;product[4]+=top;for k in 0..8{if product[k].rem_euclid(M)as u128!=poly[j+81*k]%(M as u128){return false;}}}}true}
pub fn build_digits(a:&[u128],elements:usize)->Vec<[i8;6]>{assert_eq!(a.len(),elements*N);let mut out=vec![[0i8;6];a.len()];if elements<=PUBLIC_ELEMENTS{for d in 0..6{for e in 0..elements{for m in 0..N{out[e*N+m][d]=asset_digit((d*PUBLIC_ELEMENTS+e)*N+m);}}}if congruent(a,&out){return out;}}
for e in 0..elements{for j in 0..81{let q:[i64;8]=std::array::from_fn(|k|{let x=(a[e*N+j+81*k]%(M as u128))as i64;if x>=M/2{x-M}else{x}});let(mut r,_)=encode(q,&BASES[0],0);if r.iter().any(|v|v.abs()>32){r=encode_parent_beam(q,&BASES[0],4096,4000000).0;}verify_octet(0,q,r);for d in 0..6{for k in 0..8{assert!(r[8*d+k].abs()<=32,"generic Phi24 digit bound");out[e*N+j+81*k][d]=r[8*d+k]as i8;}}}}assert!(congruent(a,&out));out}
#[cfg(test)]mod codec_guards{use super::*;#[test]fn basis_rows_have_zero_polynomial_image(){for row in BASES[0].rows{verify_octet(0,[0;8],row);}}#[test]fn arbitrary_octets_match_independent_polynomial_oracle(){let mut state=0x243648u64;for case in 0..160{let a:Vec<u128>=(0..N).map(|j|{state^=state<<13;state^=state>>7;state^=state<<17;match case{0=>0,1=>(M-1)as u128,2=>if j%2==0{0}else{(M/2)as u128},_=>state as u128}}).collect();let r=build_digits(&a,1);assert!(r.iter().flatten().all(|x|x.unsigned_abs()<=32));assert!(congruent(&a,&r));}}}
